class Solution { fun minimumMoves(grid:Array<IntArray>):Int{val extras=mutableListOf<IntArray>();val zeros=mutableListOf<IntArray>();for(row in 0 until 3)for(col in 0 until 3){if(grid[row][col]==0)zeros.add(intArrayOf(row,col));for(count in 1 until grid[row][col])extras.add(intArrayOf(row,col))};val memo=IntArray(1 shl zeros.size){-1};fun dfs(mask:Int):Int{val index=Integer.bitCount(mask);if(index==extras.size)return 0;if(memo[mask]!=-1)return memo[mask];var answer=1000000;for(target in zeros.indices)if(mask and (1 shl target)==0){val distance=kotlin.math.abs(extras[index][0]-zeros[target][0])+kotlin.math.abs(extras[index][1]-zeros[target][1]);answer=minOf(answer,distance+dfs(mask or (1 shl target)))};memo[mask]=answer;return answer};return dfs(0)} }
